<script lang="ts">
  import {Download,FolderOpen,ChevronDown,AlertCircle,Check,LoaderCircle,ExternalLink} from 'lucide-svelte';
  import {bytes,type EngineComponent} from './engine';
  import {tooltip} from './tooltip';
  import type {Snippet} from 'svelte';
  let {component,locked=false,category='',ondownload,onimport,children}:{component:EngineComponent;locked?:boolean;category?:string;ondownload:(id:string)=>void;onimport:(id:string,folder:boolean)=>void;children?:Snippet}=$props();
</script>
<article class="engine-component" data-state={component.state}>
  <div class="component-heading"><strong>{component.label}</strong><span class="component-state" use:tooltip={component.state==='installed'?'Files match PoseSnap’s pinned catalogue.':component.message||'This component needs verification.'}>{#if component.state==='installed'}<Check size={13}/>{:else if component.state==='checking'}<LoaderCircle size={13}/>{:else}<AlertCircle size={13}/>{/if}{component.state==='installed'?'Installed':component.state==='missing'?'Missing':component.state==='checking'?'Checking':component.state==='unchecked'?'Not checked':'Needs attention'}</span></div>
  <small>{component.version} · {component.required?'Required':category|| (component.id==='expression'?'Expression studio':component.id==='clue-body'?'Optional diagnostics':'Optional fallback')} · {bytes(component.installedBytes)} installed size</small>
  {#if component.state!=='installed'&&component.message}<p class="component-message">{component.message}</p>{/if}
  {@render children?.()}
  <details class="component-location"><summary use:tooltip={'Show exact local folders, official source and download size.'}>Location &amp; source <ChevronDown size={13}/></summary>{#each component.locations as location}<code use:tooltip={location}>{location}</code>{/each}{#if component.source}<a href={component.source} target="_blank" rel="noreferrer">Official source <ExternalLink size={12}/></a>{/if}{#if component.downloadSources.length}<p>Download URLs</p>{#each component.downloadSources as url}<code use:tooltip={url}>{url}</code>{/each}{/if}<p>{component.downloadBytes===null?component.id==='clue-body'?'Optional CLUE weights require authorised upstream access. Ordinary extraction does not need CLUE.':'No automatic download is configured for this component. See the recovery options.':bytes(component.downloadBytes)+' download. PoseSnap checks and installs every part automatically.'}</p></details>
  {#if component.state!=='installed'}<div class="component-actions"><button class="secondary" disabled={locked||!component.downloadable||component.id==='browser'} onclick={()=>ondownload(component.id)} use:tooltip={component.id==='browser'?'Close the app and launch PoseSnap.exe --engine-setup to replace the private browser.':!component.downloadable?'No compatible hosted pack is configured. Use Import folder.':locked?'Finish the current task first.':'Download or resume, verify and install this component.'}><Download size={14}/>{component.state==='attention'?'Retry download':'Download'}</button><button class="secondary" disabled={locked||component.id==='browser'} onclick={()=>onimport(component.id,true)} use:tooltip={component.id==='browser'?'Import the browser through PoseSnap.exe --engine-setup while its workspace is closed.':'Import this component from a complete PoseSnap folder or its own folder. Only checksum-matching component files are copied.'}><FolderOpen size={14}/> Import folder</button>{#if component.downloadable||component.installedBytes<4e9}<button class="text-button" disabled={locked||component.id==='browser'} onclick={()=>onimport(component.id,false)} use:tooltip={'Choose the exact verified archive or model file from disk.'}>Import file</button>{/if}</div>{/if}
</article>
